    {μ : Fin r → BitInput κ → ℝ} (hμ : ∀ h x, 0 ≤ μ h x)
    (hm : 0 < ∑ V : Fin r → BitInput κ,
      if classicalPrefix T τ V then ∏ h, μ h (V h) else 0) :
    ∀ h, 0 < classicalMass (classicalTranscriptWeight μ τ h)

